/**
 * GoalQueue Types - Persistent Goals with Proactive Reminders
 */

export type GoalStatus = "active" | "paused" | "completed" | "cancelled" | "archived";

export type GoalPriority = "high" | "medium" | "low";

export type Goal = {
  id: string;
  title: string;
  description?: string;
  status: GoalStatus;
  priority: GoalPriority;
  createdAt: number;
  updatedAt: number;
  deadline?: number;
  progress?: number; // 0-100
  tags?: string[];
  metadata?: Record<string, unknown>;
  reminderSchedule?: ReminderSchedule;
  parentGoalId?: string;
  subGoalIds?: string[];
  nextReminderAt?: number; // Event-driven reminder check
  streak?: number; // Consecutive completions
  snoozeCount?: number; // Number of times snoozed
  originalDeadline?: number; // Original deadline before snoozing
};

// ============================================================================
// DEPENDENCIES - Temporal relationships between goals
// ============================================================================

export type DependencyType = "blocks" | "requires" | "parallel";

export type GoalDependency = {
  id: string;
  blockerGoalId: string; // This goal must be done first
  blockedGoalId: string; // Before this goal can start
  dependencyType: DependencyType;
  lagMinutes: number; // Buffer time after blocker completes
  createdAt: number;
};

// ============================================================================
// CONTEXT RULES - Smart reminder triggers
// ============================================================================

export type ContextType = "location" | "time_pattern" | "streak" | "device_state" | "energy";

export type ContextRule = {
  id: string;
  goalId: string;
  contextType: ContextType;
  contextData: Record<string, unknown>; // {lat, lng, radius} or {hour: 9, dayOfWeek: [1,2,3]}
  priorityBoost: number; // +1 to +3 urgency boost
  enabled: boolean;
  lastTriggered?: number;
  triggerCount: number;
};

// ============================================================================
// REMINDERS
// ============================================================================

export type ReminderSchedule = {
  enabled: boolean;
  frequency: "daily" | "weekly" | "custom";
  customCron?: string;
  quietHours?: { start: number; end: number };
  lastReminder?: number;
  nextReminder?: number;
};

// ============================================================================
// CONFIG & STATS
// ============================================================================

export type GoalQueueConfig = {
  enabled: boolean;
  agentId: string;
  storePath?: string;
  reminderIntervalMs: number;
  maxActiveGoals: number;
  autoRemind: boolean;
  quietHours: { start: number; end: number };
  archiveAfterDays: number; // Move completed goals to archive after N days
};

export type GoalQueueStats = {
  totalGoals: number;
  activeGoals: number;
  completedGoals: number;
  overdueGoals: number;
  archivedGoals: number;
  nextReminder?: number;
  blockedGoals: number;
  avgStreak: number;
};

// ============================================================================
// RECURRING TASKS - Blueprint/template for habits
// ============================================================================

export type RecurrenceFrequency = "daily" | "weekly" | "monthly" | "custom";

export type RecurrenceBlueprint = {
  id: string;
  title: string;
  description?: string;
  frequency: RecurrenceFrequency;
  customCron?: string; // e.g. "0 9 * * 1-5" = weekdays at 9am
  tags?: string[];
  priority: GoalPriority;
  reminderSchedule?: ReminderSchedule;
  active: boolean;
  createdAt: number;
  lastGeneratedAt?: number;
  nextDueAt?: number;
};

// ============================================================================
// SNOOZE - Auto-deferral for overdue noise reduction
// ============================================================================

export type SnoozeReason = "user_requested" | "auto_overdue" | "context_mismatch";

export type SnoozeConfig = {
  maxAutoSnoozes: number; // Max auto-snoozes before user must act (default: 3)
  snoozeDurationMs: number; // Default snooze time (default: 4 hours)
  escalateAfterDays: number; // Escalate priority after N days overdue
};

export type SnoozeEvent = {
  goalId: string;
  snoozedAt: number;
  snoozedUntil: number;
  reason: SnoozeReason;
  snoozeCount: number; // Total snoozes for this goal
};

// ============================================================================
// EVENT SOURCING - Audit trail for ML/optimization
// ============================================================================

export type GoalEventType =
  | "created"
  | "updated"
  | "status_changed"
  | "completed"
  | "archived"
  | "snoozed"
  | "dependency_added"
  | "dependency_removed"
  | "context_rule_added"
  | "reminder_sent"
  | "streak_updated"
  | "progress_updated"
  | "recurrence_generated";

export type GoalEvent = {
  id: string;
  goalId: string;
  eventType: GoalEventType;
  eventTime: number;
  data: Record<string, unknown>; // Event-specific payload
  metadata?: {
    source: "user" | "system" | "automation";
    sessionId?: string;
    correlationId?: string;
  };
};

