function getBucketDuration(bucket: TimeBucket): number {
  const durations: Record<TimeBucket, number> = {
    minute: 60 * 1000,
    hour: 60 * 60 * 1000,
    day: 24 * 60 * 60 * 1000,
    week: 7 * 24 * 60 * 60 * 1000,
    month: 30 * 24 * 60 * 60 * 1000,
  };
  return durations[bucket];
}

